CREATE TABLE IF NOT EXISTS categories(id INTEGER PRIMARY KEY,name TEXT NOT NULL UNIQUE COLLATE NOCASE);
CREATE TABLE IF NOT EXISTS regulations(id INTEGER PRIMARY KEY,number TEXT NOT NULL,year INTEGER NOT NULL CHECK(year BETWEEN 1900 AND 2200),title TEXT NOT NULL,category_id INTEGER NOT NULL REFERENCES categories(id),issued_on TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('Berlaku','Dicabut')),status_note TEXT NOT NULL,note TEXT NOT NULL,published INTEGER NOT NULL DEFAULT 0 CHECK(published IN(0,1)),archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN(0,1)),UNIQUE(category_id,number,year));
CREATE TABLE IF NOT EXISTS documents(id INTEGER PRIMARY KEY,regulation_id INTEGER NOT NULL REFERENCES regulations(id),token TEXT NOT NULL UNIQUE,sha256 TEXT NOT NULL,size INTEGER NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%SZ','now')));
CREATE TABLE IF NOT EXISTS links(id INTEGER PRIMARY KEY,source_id INTEGER NOT NULL REFERENCES regulations(id),target_id INTEGER NOT NULL REFERENCES regulations(id),kind TEXT NOT NULL CHECK(kind IN('Mengubah','Mencabut')),note TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id),CHECK(source_id<>target_id),UNIQUE(source_id,target_id,kind));
